"""Independent protected INDX recipes/expectations; only generated byte buffers."""
import argparse
import copy
import json
import struct
import subprocess
from pathlib import Path
from test_ntfs_index import entry, filename, reference, canonical, sha, compare


def block(size=1024, usa=40, first=None, rows=None, children=False, vbn=0, sequence=0x73a1):
    rows = [entry(), entry(end=True)] if rows is None else rows
    count = size // 512 + 1
    first = ((usa + count * 2 - 24 + 7) & ~7) if first is None else first
    body = b''.join(row[0] for row in rows)
    logical = bytearray((i * 37 + i // 5) & 255 for i in range(size))
    logical[:4] = b'INDX'
    struct.pack_into('<HHQQIIIB', logical, 4, usa, count, (1 << 64) - 1, vbn,
                     first, first + len(body), size - 24, int(children))
    logical[37:40] = b'\xf4\xf5\xf6'
    logical[24 + first:24 + first + len(body)] = body
    assert len(logical) == size and usa + count * 2 <= 24 + first
    tails = [logical[i - 2:i] for i in range(512, size + 1, 512)]
    struct.pack_into('<H', logical, usa, sequence)
    for i, tail in enumerate(tails):
        logical[usa + (i + 1) * 2:usa + (i + 2) * 2] = tail
    raw = bytearray(logical)
    for i in range(512, size + 1, 512):
        struct.pack_into('<H', raw, i - 2, sequence)
    facts = dict(fields_present=True, fixups_valid=True, envelope_valid=True, issues=0,
                 usa_offset=usa, usa_count=count, update_sequence=sequence,
                 strides=size // 512, mismatched_tails=0, log_sequence=str((1 << 64) - 1),
                 vbn=str(vbn), first=first, used=first + len(body), allocated=size - 24,
                 flags=int(children))
    items = [dict(issues=0, present=True, end=row[1]['end_marker'],
                  child=row[1]['child_vbn'], reference=row[1]['segment_reference'],
                  name_hex=row[1]['filename']['name_hex']) for row in rows]
    return raw, bytes(logical), facts, items


def cases():
    def case(label, raw, wanted_fields=None, size=1024, vbn=0, **controls):
        request = dict(hex=bytes(raw).hex(), major='3', minor='1', expected=str(size),
                       vbn=str(vbn), mode='begin', budget='4096', alias='none', capacity=str(len(raw)))
        request.update({k: str(v) for k, v in controls.items()})
        wanted = dict(status=0, observe_unchanged=False, input_unchanged=True)
        wanted.update(wanted_fields or {})
        if wanted.get('restore_status', 0):
            wanted.update(output_unchanged=True, restore_observation_unchanged=True, cursor_unchanged=True)
        return label, request, wanted
    for size in (512, 1024, 2048, 4096, 8192, 16384, 32768):
        for minor in (0, 1):
            raw, logical, facts, items = block(size=size)
            yield case(f'size-{size}-profile-{minor}', raw, dict(block=facts, restore_status=0,
                       restored_hex=logical.hex(), output_tail_unchanged=True, items=items,
                       entry_count=2, entry_issues=0, terminated=True, cursor_unchanged=False), size=size, minor=minor)
        for stride in range(size // 512):
            broken = bytearray(raw); broken[(stride + 1) * 512 - 2] ^= 1
            yield case(f'torn-{size}-{stride}', broken, dict(block=dict(issues=64, mismatched_tails=1,
                       fixups_valid=False, envelope_valid=False), restore_status=1), size=size)
    raw, logical, facts, items = block()
    for n in range(1024):
        expected = dict(issues=3, fields_present=False, fixups_valid=False, envelope_valid=False)
        if n >= 40:
            expected.update(issues=2 | 32 | 128 | (16 if n < 46 else 0), fields_present=True,
                            strides=n // 512, usa_offset=40, usa_count=3, update_sequence=0,
                            mismatched_tails=0)
        yield case(f'byte-truncation-{n}', raw[:n], dict(block=expected, restore_status=1))
    yield case('trailing-extra-byte', raw + b'\xee', dict(block=dict(issues=2, fixups_valid=False,
               envelope_valid=False), restore_status=1))
    mutations = [
        ('bad-signature', 0, '4s', b'BAAD', 4),
        ('usa-too-early', 4, 'H', 38, 16),
        ('usa-odd', 4, 'H', 41, 16),
        ('usa-over-first-entry', 4, 'H', 44, 128 | 64),
        ('usa-stride-tail', 4, 'H', 506, 16 | 128),
        ('usa-beyond-first-stride', 4, 'H', 512, 16 | 128),
        ('usa-max', 4, 'H', 65535, 16 | 128),
        ('count-zero', 6, 'H', 0, 32),
        ('count-short', 6, 'H', 2, 32),
        ('count-extra', 6, 'H', 4, 32),
        ('count-multiplication-limit', 6, 'H', 255, 32 | 16 | 128),
        ('count-over-limit', 6, 'H', 256, 32 | 16),
        ('count-max', 6, 'H', 65535, 32 | 16),
        ('first-before-array', 24, 'I', 16, 128),
        ('first-unaligned', 24, 'I', 25, 128),
        ('first-used-overflow', 24, 'I', 0xfffffff8, 128),
        ('used-before-first', 28, 'I', 23, 128),
        ('used-short-terminal', 28, 'I', 39, 128),
        ('used-beyond-allocation', 28, 'I', 1001, 128),
        ('used-max', 28, 'I', 0xffffffff, 128),
        ('allocation-short', 32, 'I', 23, 128),
        ('allocation-over-raw', 32, 'I', 1001, 128),
        ('allocation-max', 32, 'I', 0xffffffff, 128),
        ('unknown-flags', 36, 'B', 2, 256),
        ('all-flags', 36, 'B', 255, 256),
        ('vbn-mismatch', 16, 'Q', 1, 512),
        ('negative-vbn', 16, 'Q', 1 << 63, 512),
    ]
    for label, at, fmt, value, issue in mutations:
        broken = bytearray(raw); struct.pack_into('<' + fmt, broken, at, value)
        valid_fixups = not (issue & (16 | 32 | 64))
        yield case(label, broken, dict(block=dict(issues=issue, envelope_valid=False,
                   fixups_valid=valid_fixups), restore_status=1))
    for size in (512, 1024, 32768):
        count = size // 512 + 1
        for offset in (40, 510 - count * 2):
            # The legal latest array can force entries into a later stride.
            if 24 + ((offset + count * 2 - 24 + 7) & ~7) + 16 > size:
                continue
            b, restored, info, rows = block(size=size, usa=offset, rows=[entry(end=True)])
            yield case(f'legal-usa-{size}-{offset}', b, dict(block=info, restored_hex=restored.hex(),
                       restore_status=0, items=rows, terminated=True), size=size)
    for label, changes in [('profile-major', dict(major=2)), ('profile-minor', dict(minor=2))]:
        yield case(label, raw, dict(status=1, observe_unchanged=True, restore_status=1), **changes)
    for value in (0, 1, 511, 513, 49152, 65536, 0xffffffff):
        yield case(f'invalid-expected-size-{value}', raw,
                   dict(status=7, observe_unchanged=True, restore_status=7), expected=value)
    yield case('negative-expected-vbn', raw, dict(status=7, observe_unchanged=True, restore_status=7), vbn=1 << 63)
    yield case('raw-over-cap', bytearray(49153), dict(status=7, observe_unchanged=True, restore_status=7))
    for capacity in (0, 1, 1023):
        yield case(f'short-capacity-{capacity}', raw, dict(block=facts, restore_status=3), capacity=capacity)
    for alias in ('same', 'forward', 'backward'):
        yield case(f'alias-{alias}', raw, dict(block=facts, restore_status=1), alias=alias)
    for budget in (0, 4097):
        yield case(f'bad-budget-{budget}', raw, dict(block=facts, restore_status=7), budget=budget)
    for budget in (1, 2):
        if budget == 1:
            expected_items = [items[0], dict(issues=1024, present=False, end=False)]
            yield case('quota-before-terminal', raw, dict(block=facts, restore_status=0,
                       items=expected_items, entry_count=1, entry_issues=1024, terminated=False), budget=budget)
        else:
            yield case('exact-terminal-quota', raw, dict(block=facts, restore_status=0, items=items,
                       entry_count=2, entry_issues=0, terminated=True), budget=budget)
    for vbn in (0, 0xffffffffffff, (1 << 63) - 1):
        b, restored, info, rows = block(vbn=vbn, sequence=0)
        yield case(f'full-vbn-zero-sequence-{vbn}', b, dict(block=info, restore_status=0,
                   restored_hex=restored.hex(), items=rows, terminated=True), vbn=vbn)
    # Place a long original name across a protected tail; each expected name is
    # derived directly from its original recipe, never from native output.
    long_name = bytes([0x1b, 0, 0, 0xd8, 0xff, 0xdc]) * 85
    for children in (False, True):
        rows = [entry(key=filename(long_name), child=0x123456789 if children else None),
                entry(end=True, child=0xabcdef if children else None)]
        b, restored, info, expected_rows = block(size=2048, rows=rows, children=children)
        yield case(f'cross-stride-name-{children}', b, dict(block=info, restore_status=0,
                   restored_hex=restored.hex(), items=expected_rows, entry_issues=0, terminated=True), size=2048)
    # A child trailer's last bytes lie at a stride tail and must be restored.
    rows = [entry(child=0x123456789abcdef, padding=344), entry(end=True, child=0)]
    b, restored, info, expected_rows = block(size=1024, first=48, rows=rows, children=True)
    assert 24 + 48 + len(rows[0][0]) == 512
    yield case('cross-stride-child', b, dict(block=info, restore_status=0,
               restored_hex=restored.hex(), items=expected_rows, entry_issues=0, terminated=True))
    b, restored, info, rows = block(rows=[entry()])
    yield case('missing-terminal-after-restore', b, dict(block=info, restore_status=0,
               items=[rows[0], dict(issues=512, present=False)], entry_issues=512, terminated=False))
    yield case('restore-only', raw, dict(block=facts, restore_status=0, restored_hex=logical.hex(),
               cursor_unchanged=True), mode='restore', capacity=1040)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--probe', type=Path, required=True)
    ap.add_argument('--output', type=Path, required=True)
    args = ap.parse_args()
    rows = list(cases())
    receipts = []
    for at in range(0, len(rows), 8):
        batch = rows[at:at + 8]
        p = subprocess.run([str(args.probe.resolve())], input=canonical([r[1] for r in batch]),
                           capture_output=True, timeout=40)
        assert p.returncode == 0 and not p.stderr, (batch[0][0], p.returncode, p.stderr.decode(errors='replace'))
        results = json.loads(p.stdout)
        assert len(results) == len(batch)
        for (label, request, wanted), actual in zip(batch, results):
            compare(actual, wanted, label)
            receipts.append(dict(case=label, input_sha256=sha(canonical(request)),
                                 expectation_sha256=sha(canonical(wanted)), result_sha256=sha(canonical(actual)), passed=True))
    args.output.write_text(json.dumps(dict(count=len(receipts), cases=receipts,
        scope='Private supplied-byte INDX observation/restoration/entries; no native directory acquisition or full filesystem qualification',
        physical_devices=False), indent=2) + '\n', encoding='utf-8', newline='\n')
    print(len(receipts), 'guarded INDX cases passed')

if __name__ == '__main__':
    main()
